"""Public-only author and critic prompts for frozen task realization."""
from __future__ import annotations
import json
from typing import Any,Mapping
_AUTHOR_SYSTEM="""Rewrite the deterministic draft into one natural benchmark question while preserving the frozen public task contract exactly. You may improve wording only. Preserve operand ownership, relation direction, union versus intersection, all public values, and the terminal contract. Every date, number and attribute condition MUST remain attached to the same grammatical entity (e.g. a condition on a Way cannot move to a City). Keep the complete relation-hop chain (e.g. person -> death place -> spouse), including each intermediate owner; do not replace a multi-hop path with a direct attribute of its starting entity. Preserve every explicitly named public starting entity or identifying anchor already in the deterministic draft (e.g. Kingswell Airport). Never replace it with a non-unique attribute clue or move its attributes to downstream entities. Prefer a natural starting clue and final ask; do not narrate acquisition steps. QUERY_NAME returns all matching entities. VERIFY asks whether any recorded value satisfies the claim. Do not add facts, resources, proof requirements, hidden criteria, or answer hints. Do not reveal internal resource ids, capability ids, orchestration labels, or hidden acquisition structure. Return JSON: {\"question\": \"...\", \"notes\": \"brief wording note\"}."""
_CRITIC_SYSTEM="""Check whether the candidate question has exactly the same public semantics as the frozen contract. Reject changed operators, missing operands, changed quantifiers, changed comparison direction, invented constraints/resources, answer leakage, or wording that exposes hidden acquisition semantics. Perform an explicit clause-by-clause comparison against the deterministic draft BEFORE deciding: (1) for every date, number or attribute condition, identify the specific entity or intermediate result it modifies in BOTH sentences; reject moving a Way start-date condition onto a City, even if the year remains present; (2) for each relation hop, preserve its source, target, direction, and intermediate links; reject collapsing a death-place -> spouse chain into a direct property of the person; (3) preserve AND/OR, intersection/union, quantifiers and final output target. Treat matching keywords or numerical values as insufficient evidence of semantic equivalence. Check that every explicitly named public starting entity in the draft remains in the candidate. Reject dropping an anchor name merely because some other attribute values remain present; an IATA code need not uniquely identify an airport. The deterministic draft is the complete reference public question; task_design.public_clues may describe only part of its operands. Never delete another operand merely because it is absent from public_clues. Requested attributes, ranking directions, verification targets and public identifying names explicitly present in the draft are legitimate question content, not oracle answers. Hidden answer values are never supplied to you. Local checks already verify exact public number/literal presence; trust their passed result rather than inventing missing-value errors. Give at most three concise issues describing the exact changed constraint owner or missing hop, no analysis or self-correction, and a compact repair only when needed. If any substantive issue remains, accept must be false and semantic_fidelity must be fail. If accept is true, issues MUST be empty. Cosmetic changes are allowed. Return JSON: {\"accept\": true|false, \"semantic_fidelity\": \"pass|fail\", \"issues\": [\"...\"], \"repair_question\": \"...\"}. If repair is possible, repair wording only; never change the contract."""
def author_prompt(payload:Mapping[str,Any],*,retry_feedback:str|None=None)->str:
    public={"draft_question":payload.get("draft_question"),"task_design":payload.get("task_design",{}),"terminal_contract":payload.get("terminal_contract",{}),"resources":payload.get("resources",()),"available_agents":payload.get("available_agents",())};parts=[_AUTHOR_SYSTEM,"\nFrozen public task:\n"+json.dumps(public,ensure_ascii=False,indent=2)]
    if retry_feedback:parts.append("\nPrevious deterministic/critic feedback:\n"+retry_feedback+"\nRepair only those wording defects.")
    return "\n".join(parts)
def critic_prompt(payload:Mapping[str,Any],question:str)->str:
    from .validators import preflight
    local_checks=preflight(payload,question).to_dict()
    public={"draft_question":payload.get("draft_question"),"task_design":payload.get("task_design",{}),"terminal_contract":payload.get("terminal_contract",{}),"resources":payload.get("resources",())};return _CRITIC_SYSTEM+"\n\nDeterministic local checks: "+json.dumps(local_checks)+"\n\nFrozen public task:\n"+json.dumps(public,ensure_ascii=False,indent=2)+"\n\nCandidate question:\n"+str(question)
__all__=["author_prompt","critic_prompt"]
